INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type, fixed_at) VALUES
('eye_contact_sheet_label_strip_is_flush_against_the_next_row_so_a_reader_binds_it_to_the_wrong_thumbnail', 'THE EYE contact sheet composites each time label directly beneath its thumbnail with the next row starting immediately after, so the label is equidistant from its own frame and the one below and an automated reader attributes every cell one row (2.8 s) ahead', 'MODERATE', 'peter_parker:visual_validator', 'composeGrid (src/lib/validators/visual/contactSheet.ts): cellH = THUMB_H + LABEL_H; thumbnail i at top = row * cellH; its label strip at top = row * cellH + THUMB_H; the next row''s thumbnails at (row + 1) * cellH, i.e. immediately below the strip with zero gap, and the strip fill (#1a1a30) is a near-background dark. Nothing visually binds a strip to the frame above rather than the frame below. MEASURED CONSEQUENCE: the eye-walker on solids_of_revolution run 20260828-095046 read STATE_6 cells "labelled t=8400/9100/9800" as showing the dissolved ring stack and formula, while the dense dumps at those exact times are MD5-identical to t=7700 and t=10500 (the held wrong solid, verified here: five identical hashes) — it had bound each strip to the row beneath, GRID_COLS = 4 cells x 700 ms = 2.8 s ahead, and reported a "~2.6 s skew" on two states. It then proposed the thumbnails came from a separately-timed pass. They do not: both the sheet and the dumps are written from the same frames_b64 / capture_times_ms (frameDump.ts). The data is right; the layout invites the misread. WHY IT MATTERS: the sheet is what CLAUDE.md says to read FIRST, and a wrong binding turns a correct sim into a false finding — this one cost a walker dispatch and would have been filed as a harness defect had the code not been read.', 'A label must be visually bound to the thing it labels: draw it INSIDE the thumbnail (top-left overlay) or leave a gap/border between a row''s label strip and the next row that is larger than the strip-to-thumbnail distance. Any grid where the caption sits equidistant between two images will be misread by some reader, human or automated, and a sheet meant to be read first must not depend on the reader guessing the binding.', 'js_eval', 'Render a sheet for a state whose dense frames change every cell; for each label strip, measure the vertical gap to the thumbnail above (should be 0) and to the thumbnail below (currently also 0). Assert the below-gap is >= LABEL_H or the label is composited inside the thumbnail bounds. The negative control is the current layout: both gaps 0.', 'OPEN', ARRAY['solids_of_revolution']::text[], ARRAY[]::text[], 'session_2026-08-28_sr_checkpoint_b', 'incident', NULL)
ON CONFLICT (bug_class) DO UPDATE SET
  title = EXCLUDED.title,
  severity = EXCLUDED.severity,
  owner_cluster = EXCLUDED.owner_cluster,
  root_cause = EXCLUDED.root_cause,
  prevention_rule = EXCLUDED.prevention_rule,
  probe_logic = EXCLUDED.probe_logic,
  status = EXCLUDED.status,
  concepts_affected = EXCLUDED.concepts_affected,
  fixed_in_files = EXCLUDED.fixed_in_files,
  fixed_at = EXCLUDED.fixed_at
WHERE engine_bug_queue.root_cause NOT LIKE '%EYE_SHEET_LABEL_BINDING_2026_08_28%'
  AND engine_bug_queue.status NOT IN ('FIXED', 'FALSE_POSITIVE');

